// Independent real-browser checks. --list never starts Chrome; case-name filters
// preserve previous evidence so only changed boundaries need to be rerun.
const base = process.env.VERIFY_BASE_URL || 'http://127.0.0.1:3039'
const out = resolve('docs/verify/2026-11-17-repeat-batch26/browser')
const only = process.argv[2]
const messages = Object.fromEntries(['ko', 'en'].map(language => [language, JSON.parse(readFileSync(`messages/${language}.json`, 'utf8'))]))
const tr = (ns, key, language = 'ko', values = {}) => {
  const value = key.split('.').reduce((object, key) => object?.[key], messages[language][ns])
  assert.equal(typeof value, 'string', `Missing ${language}:${ns}.${key}`)
  return value.replace(/\{(\w+)\}/g, (match, key) => values[key] ?? match)
}
const cv = (key, language = 'ko', values = {}) => tr('jsonCsvConverter', key, language, values)
const b64 = (key, language = 'ko', values = {}) => tr('base64Converter', key, language, values)
const button = (scope, name) => scope.getByRole('button', { name, exact: true })
const wait = ms => new Promise(resolve => setTimeout(resolve, ms))
async function poll(predicate, description, attempts = 180) { for (let n = 0; n < attempts; n++) { if (await predicate()) return; await wait(100) }; assert.fail(`Timed out: ${description}`) }
const cases = [], results = []
const test = (name, fn, options = {}) => cases.push({ name, fn, options })

async function run(browser, { name, fn, options }) {
  if (only && !only.split(',').some(part => name.includes(part))) return
  const context = await browser.newContext({ viewport: { width: options.width ?? 1280, height: 900 }, timezoneId: 'Asia/Seoul', serviceWorkers: 'block', permissions: ['clipboard-read', 'clipboard-write'], acceptDownloads: true })
  const errors = [], hydration = [], external = [], consoleErrors = [], network = [], logs = []
  await context.addInitScript(options => {
    if (!/^https?:$/.test(location.protocol)) return
    if (!localStorage.getItem('__batch26Seeded')) { localStorage.setItem('language', options.language ?? 'ko'); localStorage.setItem('theme', options.dark ? 'dark' : 'light'); localStorage.setItem('__batch26Seeded', '1') }
    window.__unhandled = []; addEventListener('unhandledrejection', event => window.__unhandled.push(String(event.reason)))

  }, options)
  await context.route('**/*', route => { const request = route.request(); network.push(request.url() + '\n' + (request.postData() ?? '')); const url = new URL(request.url()); if (url.origin === base || ['blob:', 'data:'].includes(url.protocol)) return route.continue(); external.push(url.href); return route.abort('blockedbyclient') })
  context.on('page', page => {
    page.setDefaultTimeout(16000); page.setDefaultNavigationTimeout(120000)
    page.on('pageerror', error => errors.push(error.stack ?? String(error)))
    page.on('console', message => { logs.push(message.text()); if (message.type() === 'error') { consoleErrors.push(message.text()); if (/hydration|hydrating|did not match|Minified React error/i.test(message.text())) hydration.push(message.text()) } })
    page.on('dialog', dialog => dialog.accept())
  })
  const page = await context.newPage()
  page.__verificationSecrets = []
  const redact = value => { let text = String(value); if (options.sensitive) for (const secret of page.__verificationSecrets.filter(value => value.length >= 4)) text = text.replaceAll(secret, '[redacted generated value]'); return text }
  const open = async (slug, query = '', target = page) => {
    await target.goto(`${base}/${slug}/${query}`, { waitUntil: 'domcontentloaded' }); await target.locator('main h1').first().waitFor()
    await target.waitForFunction(() => [...document.querySelectorAll('[data-language-toggle] button')].some(element => Object.keys(element).some(key => key.startsWith('__reactProps$')))); await wait(200)
  }
  let status = 'pass', detail = {}, error
  const watchdog = setTimeout(() => { void context.close().catch(() => {}) }, 120000)
  try { detail = await fn({ page, context, open, network, logs }) ?? {}; assert.deepEqual(errors, [], 'JS page errors'); assert.deepEqual(hydration, [], 'Hydration errors'); for (const active of context.pages()) assert.deepEqual(await active.evaluate(() => window.__unhandled), [], 'Unhandled rejections'); assert.ok(!/\b(?:jsonCsvConverter|base64Converter)\.[a-zA-Z][\w.]+/.test(await page.locator('body').innerText()), 'Raw translation key') }
  catch (cause) { status = 'fail'; error = redact(cause.stack ?? String(cause)); await page.screenshot({ path: resolve(out, `${name}-failure.png`), caret: 'initial', mask: options.sensitive ? [page.locator('[data-password-value]'), page.locator('[data-password-copy-recovery] textarea'), page.locator('#pg-check')] : [] }).catch(() => {}); writeFileSync(resolve(out, `${name}-failure.txt`), `${error}\n\n${options.sensitive ? 'Sensitive page body intentionally omitted.' : await page.locator('body').innerText().catch(() => '')}`) }
  const result = { name, status, checkedAt: new Date().toISOString(), ...detail, error, errors: errors.map(redact), hydration: hydration.map(redact), consoleErrors: consoleErrors.map(redact), external: [...new Set(external)].map(redact) }
  clearTimeout(watchdog); results.push(result); writeFileSync(resolve(out, `${name}-evidence.json`), JSON.stringify(result, null, 2)); console.log(`${status.toUpperCase()} ${name}${error ? `: ${error.split('\n')[0]}` : ''}`); await context.close()
}
async function changeLanguage(page, language) {
  await page.evaluate(() => scrollTo({ top: 0, behavior: 'instant' })); const toggle = page.locator('[data-language-toggle]:visible').first()
  await toggle.locator('button[aria-expanded]').click(); await toggle.getByRole('button', { name: language === 'en' ? 'English' : '한국어', exact: true }).last().click()
}
async function screenshot(page, name, panel) {
  if (panel) { await panel.evaluate(element => element.scrollIntoView({ block: 'center', behavior: 'instant' })); await panel.screenshot({ path: resolve(out, `${name}-panel.png`), caret: 'initial' }) }
  await page.evaluate(() => scrollTo({ top: 0, behavior: 'instant' })); await page.screenshot({ path: resolve(out, `${name}-top.png`), caret: 'initial' })
}
async function mobile(page, fields, controls) {
  const box = await page.evaluate(() => ({ viewport: innerWidth, body: document.body.scrollWidth, document: document.documentElement.scrollWidth }))
  assert.ok(box.body <= box.viewport + 1 && box.document <= box.viewport + 1, JSON.stringify(box)); assert.equal(await page.evaluate(() => document.documentElement.classList.contains('dark')), true)
  for (const field of fields) assert.ok(await field.evaluate(node => parseFloat(getComputedStyle(node).fontSize)) >= 16)
  for (const control of controls) assert.ok((await control.boundingBox()).height >= 44)
  return box
}
async function download(page, action, filename) {
  const pending = page.waitForEvent('download'); await action(); const file = await pending; const path = resolve(out, filename ?? file.suggestedFilename()); await file.saveAs(path)
  const bytes = readFileSync(path); return { filename: file.suggestedFilename(), path, bytes, text: bytes.toString('utf8') }
}

// This oracle parses valid CSV downloads by matching complete quoted/unquoted
// fields. It neither imports nor calls the product's record parser.
function parseCsvOracle(source, delimiter = ',') {
  const text = source.startsWith('\uFEFF') ? source.slice(1) : source
  if (!text) return []
  const escape = value => value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  const field = new RegExp(`"(?:[^"]|"")*"|[^"${escape(delimiter)}\\r\\n]*`, 'y')
  const records = []; let row = [], position = 0
  while (true) {
    field.lastIndex = position; const match = field.exec(text); assert.ok(match, `CSV oracle: invalid field at ${position}`)
    const token = match[0]; row.push(token.startsWith('"') ? token.slice(1, -1).replace(/""/g, '"') : token); position = field.lastIndex
    if (position === text.length) { records.push(row); break }
    if (text[position] === delimiter) { position++; continue }
    assert.ok(text[position] === '\r' || text[position] === '\n', `CSV oracle: invalid separator at ${position}`)
    const ending = text.startsWith('\r\n', position) ? 2 : 1; position += ending; records.push(row); row = []; if (position === text.length) break
  }
  return records
}
const hash = bytes => createHash('sha256').update(bytes).digest('hex')
const file = (name, buffer, mimeType = 'application/octet-stream') => ({ name, buffer: Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer), mimeType })
const csvSpecial = 'id,big,note,empty,__proto__,constructor,hasOwnProperty\r\n00123,9007199254740993," 앞 공백\r\n쉼표,와 ""인용""\n끝 ",,proto-value,ctor-value,own-value\r\n'
const csvSpecialExpected = [Object.fromEntries([['id', '00123'], ['big', '9007199254740993'], ['note', ' 앞 공백\r\n쉼표,와 "인용"\n끝 '], ['empty', ''], ['__proto__', 'proto-value'], ['constructor', 'ctor-value'], ['hasOwnProperty', 'own-value']])]
const eucKrCsv = Buffer.concat([Buffer.from('name,id\r\n'), Buffer.from('c7d1b1db', 'hex'), Buffer.from(',00123\r\n')])
function pngFixture() { const png = new PNG({ width: 12, height: 8 }); for (let i = 0; i < png.data.length; i += 4) { png.data[i] = 50; png.data[i + 1] = 150; png.data[i + 2] = 230; png.data[i + 3] = 255 }; return PNG.sync.write(png) }
const binaryFixture = Buffer.from(Array.from({ length: 4096 }, (_, i) => i % 256))

async function observeFileActions(context) {
  await context.addInitScript(() => {
    window.__fileModes = {}; window.__filePending = []; window.__fileCalls = []; window.__objectUrls = []; window.__storageWrites = []
    const read = File.prototype.arrayBuffer; File.prototype.arrayBuffer = async function() { window.__fileCalls.push({ name: this.name, size: this.size }); const bytes = await read.call(this); const mode = window.__fileModes[this.name]; if (mode === 'hold') await new Promise((resolve, reject) => window.__filePending.push({ name: this.name, resolve, reject })); if (mode === 'fail') throw new DOMException('Controlled file read failure', 'NotReadableError'); return bytes }
    window.__releaseFile = (name, reject = false) => { window.__fileModes[name] = ''; const selected = window.__filePending.filter(item => item.name === name); window.__filePending = window.__filePending.filter(item => item.name !== name); for (const item of selected) reject ? item.reject(new Error('Late controlled failure')) : item.resolve() }
    const Reader = window.FileReader; window.FileReader = class extends Reader { readAsArrayBuffer(file) { window.__fileCalls.push({ name: file.name, size: file.size, reader: true }); const load = this.onload, error = this.onerror; this.onload = event => { const mode = window.__fileModes[file.name]; if (mode === 'hold') window.__filePending.push({ name: file.name, resolve: () => load?.call(this, event), reject: () => error?.call(this, new Event('error')) }); else if (mode === 'fail') error?.call(this, new Event('error')); else load?.call(this, event) }; return super.readAsArrayBuffer(file) } }
    const NativeImage = window.Image; window.__previewImageLoads = 0; window.Image = class extends NativeImage { constructor(...args) { super(...args); window.__previewImageLoads++ } }
    const create = URL.createObjectURL.bind(URL), revoke = URL.revokeObjectURL.bind(URL); URL.createObjectURL = blob => { const url = create(blob); window.__objectUrls.push({ url, type: blob.type, size: blob.size, revoked: false }); return url }; URL.revokeObjectURL = url => { const record = window.__objectUrls.find(item => item.url === url); if (record) record.revoked = true; return revoke(url) }
    const set = Storage.prototype.setItem; Storage.prototype.setItem = function(key, value) { window.__storageWrites.push({ key, value: String(value) }); return set.call(this, key, value) }
  })
}
async function clipboard(page, mode) {
  await page.evaluate(mode => { window.__nativeClipboard ??= navigator.clipboard; window.__copyPending = []; window.__fallbackCalls = 0; document.execCommand = () => { window.__fallbackCalls++; return mode === 'true' }; const value = mode === 'native' ? window.__nativeClipboard : mode === 'absent' || mode === 'true' ? undefined : { writeText: mode === 'pending' ? text => new Promise((resolve, reject) => window.__copyPending.push({ text, resolve, reject })) : () => Promise.reject(new DOMException('Controlled clipboard denial', 'NotAllowedError')) }; Object.defineProperty(navigator, 'clipboard', { configurable: true, value }) }, mode)
}
async function fillText(page, field, value) { if (value.length < 20000) await field.fill(value); else { await field.click(); await page.keyboard.press('Control+a'); await page.evaluate(value => navigator.clipboard.writeText(value), value); await page.keyboard.press('Control+v'); await poll(async () => await field.inputValue() === value.replace(/\r\n?/g, '\n'), 'large input via native paste') } }
async function privacy(args, values) { const state = await args.page.evaluate(() => ({ url: location.href, storage: JSON.stringify([localStorage, sessionStorage]), writes: window.__storageWrites })); for (const value of values.filter(value => value.length >= 12)) { assert.ok(!state.url.includes(value) && !decodeURIComponent(state.url).includes(value), 'Input/result absent from URL'); assert.ok(!state.storage.includes(value) && !state.writes.some(item => item.value.includes(value)), 'Input/result absent from storage'); assert.ok(!args.network.some(item => item.includes(value) || item.includes(encodeURIComponent(value))), 'Input/result absent from requests'); assert.ok(!args.logs.some(item => item.includes(value)), 'Input/result absent from console') }; return { testedInputResultNotPersistedOrTransmitted: true } }
async function beginResponseProbe(page) { await page.evaluate(() => { const start = performance.now(); window.__responseProbe = { start, last: start, maxGap: 0, ticks: 0 }; window.__responseInterval = setInterval(() => { const now = performance.now(), probe = window.__responseProbe; probe.maxGap = Math.max(probe.maxGap, now - probe.last); probe.last = now; probe.ticks++ }, 16) }); await wait(40) }
async function endResponseProbe(page) { await wait(50); return page.evaluate(() => { clearInterval(window.__responseInterval); const probe = window.__responseProbe; return { elapsedMs: Math.round(performance.now() - probe.start), maxTimerGapMs: Math.round(probe.maxGap), timerTicks: probe.ticks } }) }
async function spa(page, slug, query = '텍스트 변환') { await page.keyboard.press('Control+k'); await page.locator('input[aria-controls="search-listbox"]').fill(query); await page.locator(`#search-listbox a[href="/${slug}"]`).first().click(); await page.waitForURL(url => url.pathname.replace(/\/$/, '') === `/${slug}`) }

const bs = (page, name, value) => page.locator(`[data-base64-${name}${value === undefined ? '' : `="${value}"`}]`)
async function openBase64(args) { await observeFileActions(args.context); await args.open('base64-converter'); await bs(args.page, 'input').waitFor() }
async function bconvert(page) { await bs(page, 'convert').click(); await poll(async () => !(await bs(page, 'download').isDisabled()) || (await bs(page, 'error').count()) > 0, 'Base64 conversion finished') }
async function bencode(page, value) { await bs(page, 'mode', 'encode').click(); if (await bs(page, 'use-text').count()) await bs(page, 'use-text').click(); await bs(page, 'input').fill(value); await bconvert(page); return bs(page, 'output').inputValue() }
async function bdecode(page, value) { await bs(page, 'mode', 'decode').click(); await bs(page, 'input').fill(value); await bconvert(page) }
async function bfile(page, fixture) { await bs(page, 'upload').setInputFiles(fixture); await poll(async () => await bs(page, 'reading').count() === 0, 'Base64 file read completed') }

test('base64-unicode-whitespace-standard-url-padding-and-swap', async args => {
  const { page } = args; await openBase64(args); for (const text of ['f', 'foobar', '검증용 한글 😀\n두 번째 줄', ' \t\n ']) { const encoded = await bencode(page, text); assert.equal(encoded, Buffer.from(text).toString('base64')); await bs(page, 'swap').click(); assert.equal(await bs(page, 'input').inputValue(), encoded); await bconvert(page); assert.equal(await bs(page, 'output').inputValue(), text) }
  await bs(page, 'mode', 'encode').click(); await bs(page, 'format').selectOption('url'); await bfile(page, file('url.bin', Buffer.from([251, 255]))); assert.equal(await bs(page, 'output').inputValue(), '-_8'); await bs(page, 'padding').check(); assert.ok(await bs(page, 'download').isDisabled()); await bconvert(page); assert.equal(await bs(page, 'output').inputValue(), '-_8='); await bs(page, 'output-view', 'dataUrl').click(); assert.match(await bs(page, 'output').inputValue(), /;base64,\+\/8=$/); await bs(page, 'swap').click(); await bconvert(page); const result = await download(page, () => bs(page, 'download').click(), 'base64-url-two-bytes.bin'); assert.deepEqual(result.bytes, Buffer.from([251, 255])); return { unicodeAndWhitespaceByteExact: true, standardAndUrlOracleMatched: true, urlPaddingOptional: true, dataUrlAlwaysStandard: true }
})

