const cs = (page, name, value) => page.locator(`[data-json-csv-${name}${value === undefined ? '' : `="${value}"`}]`)
const ci = page => page.locator('#json-csv-input')
const co = page => page.locator('#json-csv-output')
async function openCsv(args, mode = 'jsonToCsv') { await observeFileActions(args.context); await args.open('json-csv-converter'); await cs(args.page, 'mode-button', mode).click(); await ci(args.page).waitFor() }
async function cconvert(page, error) { await cs(page, 'convert').click(); if (error) await cs(page, 'error').getByText(cv(`fidelity.errors.${error}`), { exact: true }).waitFor(); else { await poll(async () => await cs(page, 'result').getAttribute('data-json-csv-result') === 'current' && !(await cs(page, 'download').isDisabled()), 'CSV result confirmed'); assert.equal(await cs(page, 'error').count(), 0) } }
async function cupload(page, fixture, expected) { await page.locator('#json-csv-file').setInputFiles(fixture); await poll(async () => !(await cs(page, 'convert').isDisabled()), 'CSV file read ended'); if (expected !== undefined) await poll(async () => await ci(page).inputValue() === expected.replace(/\r\n?/g, '\n'), 'file decoded into input') }
async function ctable(page) { await cs(page, 'view', 'table').click(); const header = await cs(page, 'table').locator('thead th button').allTextContents(); const rows = await cs(page, 'table').locator('tbody tr').evaluateAll(nodes => nodes.map(node => [...node.querySelectorAll('td button')].map(cell => cell.textContent))); return { header, rows } }
async function cstats(page, rows, columns, bytes) { assert.equal(Number(await cs(page, 'stat', 'rows').innerText()), rows); assert.equal(Number(await cs(page, 'stat', 'columns').innerText()), columns); if (bytes !== undefined) assert.ok((await cs(page, 'stat', 'bytes').innerText()).replace(/,/g, '').includes(String(bytes))); }

